import type {Doc} from '../../src/core/types';
import {editMaterialFaces,type MaterialFaceInsertIntent} from '../../src/core/materialFaceEdit';
import {weakToolSheet,weakToolMaterial as material,weakToolAnchor} from './materialWeakTools';
import {copyMaterialComponents} from '../../src/core/materialCopy';
import {copyModelRecipe} from './materialCopyModel';
import {joinMaterialEdges} from '../../src/core/materialJoin';
export const faceModelRecipe=(doc:Doc,x=50,assignment:MaterialFaceInsertIntent['assignment']='F',fixedPart:0|1=0):MaterialFaceInsertIntent=>({kind:'material-face-insert',face:0,from:weakToolAnchor(doc,[x,0]),to:weakToolAnchor(doc,[x,100]),assignment,fixedPart,cpOnly:false});
export const faceModelSecond=(doc:Doc):MaterialFaceInsertIntent=>{const m=material(doc),crease=m.edgeSegmentIds.find((_,e)=>m.graph.edges_assignment[e]==='F')!;return {kind:'material-face-insert',face:0,from:{edgeId:crease,fraction:.5},to:{edgeId:'material-edge-1',fraction:.5},assignment:'F',fixedPart:0,cpOnly:false};};
export function faceModelCase(name:string){let d=weakToolSheet();if(name==='base')return d;const first=editMaterialFaces(d,{...faceModelRecipe(d),parametric:true});d=first.doc;if(name==='inserted')return d;d=editMaterialFaces(d,{...faceModelSecond(d),parametric:true}).doc;if(name==='two')return d;if(name==='removed'){const m=material(d);return editMaterialFaces(d,{kind:'material-face-remove',segmentIds:m.edgeSegmentIds.filter((_,e)=>m.graph.edges_assignment[e]!=='B'),parametric:true}).doc;}if(name==='ray'){const m=material(d);return editMaterialFaces(d,{kind:'material-face-ray',component:0,from:{edgeId:m.edgeSegmentIds[0],fraction:.5},through:[75,100],assignment:'F',fixedSide:'left',cpOnly:false,parametric:true}).doc;}throw Error(name);}
export function faceModelMergedBase(){const base=weakToolSheet(),source=editMaterialFaces(base,faceModelRecipe(base)).doc,m=material(source),removed=editMaterialFaces(source,{kind:'material-face-remove',segmentIds:m.edgeSegmentIds.filter((_,e)=>m.graph.edges_assignment[e]==='F'),parametric:true}).doc;return {source,removed};}
export function faceModelCrossSourceNetwork(){
 const base=weakToolSheet(),source=copyMaterialComponents(base,copyModelRecipe(base,100)).doc,m=material(source),banks=m.components.map(c=>c.edges.find(e=>m.graph.edges_vertices[e].every(v=>m.graph.vertices_coords[v][0]===100))!),joined=joinMaterialEdges(source,{kind:'material-join',pairs:[{first:m.edgeSegmentIds[banks[0]],second:m.edgeSegmentIds[banks[1]],assignment:'F'}],parametric:true}).doc,j=material(joined),merged=editMaterialFaces(joined,{kind:'material-face-remove',segmentIds:j.edgeSegmentIds.filter((_,e)=>j.graph.edges_assignment[e]==='F'),parametric:true}).doc;
 return editMaterialFaces(merged,{kind:'material-face-network',face:0,graph:{vertices:[[125,40],[140,40],[140,55],[125,55]],edges:[[0,1],[1,2],[2,3],[3,0]]},assignments:['F','F','F','F'],fixedPoint:[150,25],scope:'face',cpOnly:false,parametric:true}).doc;
}
